import { useEffect, useState } from "react";
import axios from "axios";

export default function AIContent() {
  const [content, setContent] = useState([]);

  useEffect(() => {
    fetchContent();
  }, []);

  const fetchContent = () => {
    axios
      .get("/api/ai/content")
      .then((res) => {
        console.log("AI CONTENT:", res.data); // debug
        setContent(res.data);
      })
      .catch((err) => console.log(err));
  };

  const updateStatus = async (id, status) => {
    try {
      await axios.post("/api/ai/content/status", { id, status });
      fetchContent();
    } catch (err) {
      console.log(err);
    }
  };

  return (
    <div className="p-6">
      <h1 className="text-2xl font-bold mb-6">
        🤖 AI Content Approval
      </h1>

      {content.length === 0 ? (
        <p className="text-gray-500">
          No AI content available
        </p>
      ) : (
        content.map((item) => (
          <div
            key={item.id}
            className="bg-white p-5 rounded-lg shadow mb-5 border"
          >
            {/* 🔥 FIXED: show content_type instead of topic */}
            <h2 className="font-semibold text-lg mb-2">
              {item.content_type}
            </h2>

            {/* 🔥 FIXED: content_text mapped as content */}
            <p className="text-sm text-gray-700 mb-3">
              {item.content}
            </p>

            {/* 🔥 FIXED: status mapping */}
            <p className="text-xs text-gray-500 mb-3">
              Status:{" "}
              <span
                className={
                  item.is_approved
                    ? "text-green-600 font-semibold"
                    : "text-yellow-600 font-semibold"
                }
              >
                {item.is_approved ? "Approved" : "Pending"}
              </span>
            </p>

            {/* BUTTONS */}
            <button
              onClick={() =>
                updateStatus(item.id, "approved")
              }
              className="bg-green-500 hover:bg-green-600 text-white px-3 py-1 rounded mr-2"
            >
              Approve
            </button>

            <button
              onClick={() =>
                updateStatus(item.id, "rejected")
              }
              className="bg-red-500 hover:bg-red-600 text-white px-3 py-1 rounded"
            >
              Reject
            </button>
          </div>
        ))
      )}
    </div>
  );
}
